const marketData = $('Fetch Market & CDR Data').first().json;
const bankLoans = $('Fetch Open Banking MCP Loans').first().json;

const rba = marketData.rba || {};
const sentiment = marketData.sentiment || {};
const customer = marketData.customer || {};
const loansList = bankLoans.top_recommendations || [];

const documents = [
  {
    json: {
      pageContent: `CUSTOMER PROFILE & CURRENT LOANS:\nCustomer ID: ${customer.customer_id || 'CUST_001'}\nCurrent Loans: ${JSON.stringify(customer.loans || [])}\nRisk Rating: ${customer.credit_score || 'Good'}`,
      metadata: { source: "customer_cdr_mcp", category: "customer_profile" }
    }
  },
  {
    json: {
      pageContent: `RBA CASH RATE & MONETARY SIGNALS:\nCurrent Cash Rate: ${rba.cash_rate || '4.35%'}\nRate Outlook: ${rba.outlook || 'Neutral/Hawkish'}\nLast Statement: ${rba.last_statement || 'Inflation remains above target range.'}`,
      metadata: { source: "rba_service", category: "macro_economics" }
    }
  },
  {
    json: {
      pageContent: `MARKET SENTIMENT ANALYSIS:\nSentiment Score: ${sentiment.score || 0.65}\nSentiment Summary: ${sentiment.summary || 'Market expects interest rates to hold steady before potential easing.'}`,
      metadata: { source: "sentiment_service", category: "market_insights" }
    }
  },
  {
    json: {
      pageContent: `TOP RECOMMENDED BANK BUSINESS LOAN PRODUCTS (open-banking-mcp):\n${loansList.map(l => `- ${l.bank_name || l.name}: ${l.product_name} @ ${l.interest_rate}% (Comparison: ${l.comparison_rate}%). Features: ${l.features?.join(', ')}`).join('\n')}`,
      metadata: { source: "open_banking_mcp", category: "bank_comparison" }
    }
  }
];

return documents;

// Consolidate the 20 indexed chunks into 1 single evaluation trigger event
const chunks = $input.all();

return [{
  json: {
    status: "INGESTION_COMPLETED",
    chunks_indexed: chunks.length,
    collection: "loan_advisor_rag",
    timestamp: new Date().toISOString()
  }
}];

