const evalData = $input.first().json;

const overallPct = Math.round((evalData.aggregate_metrics?.overall_ragas_score || 0) * 100);
const ctxPct = Math.round((evalData.aggregate_metrics?.context_relevance || 0) * 100);
const faithPct = Math.round((evalData.aggregate_metrics?.faithfulness || 0) * 100);
const ansPct = Math.round((evalData.aggregate_metrics?.answer_relevance || 0) * 100);

return [{
  json: {
    "🎯 EVALUATION RESULT": evalData.status || "PASSED",
    "📊 OVERALL RAGAS SCORE": `${overallPct}%`,
    "✅ PASS RATE": evalData.pass_rate || "100%",
    "📈 RAGAS QUALITY METRICS": {
      "Context Relevance": `${ctxPct}%`,
      "Faithfulness": `${faithPct}%`,
      "Answer Relevance": `${ansPct}%`
    },
    "🧪 TEST QUERIES EVALUATED": evalData.total_queries || 0,
    "📋 QUERY BREAKDOWN": (evalData.queries_evaluated || []).map(q => ({
      query: q.query,
      status: q.status,
      ragas_score: `${Math.round((q.ragas_metrics?.average_score || 0) * 100)}%`,
      answer_snippet: q.answer_snippet
    })),
    "summary_message": evalData.message || "Evaluation completed successfully.",
    "raw_eval_suite_payload": evalData
  }
}];
